* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  background:
    radial-gradient(1200px 600px at 10% -10%, #1a2540 0%, transparent 60%),
    radial-gradient(900px 500px at 110% 110%, #21183a 0%, transparent 60%),
    var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1.5rem;
}

main {
  width: 100%;
  max-width: 28rem;
}

.card {
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 1.75rem;
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.03) inset,
    0 20px 50px -20px rgba(0, 0, 0, 0.6);
}

h1 {
  margin: 0 0 0.4rem;
  font-size: 1.4rem;
  letter-spacing: -0.01em;
}

.lede {
  margin: 0 0 1.25rem;
  color: var(--text-muted);
}

.required-legend {
  margin: 0 0 1rem;
  font-size: 0.85rem;
  color: var(--text-muted);
}

.required-legend span {
  color: var(--accent-strong);
  margin-right: 0.25rem;
}

.form-field {
  background: var(--bg-elev-2);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 0.9rem 1rem;
  margin-bottom: 1.25rem;
}

.form-field.is-invalid {
  border-color: var(--danger);
  background: var(--danger-bg);
}

.checkbox-row {
  display: flex;
  align-items: flex-start;
  gap: 0.65rem;
}

.checkbox-row input[type="checkbox"] {
  /* Keep native control for proper a11y; just resize and tint */
  width: 1.15rem;
  height: 1.15rem;
  margin: 0.15rem 0 0;
  flex-shrink: 0;
  accent-color: var(--accent);
  cursor: pointer;
}

.checkbox-row label {
  cursor: pointer;
  color: var(--text);
}

.checkbox-row label span {
  color: var(--accent-strong);
  margin-left: 0.2rem;
}

a {
  color: var(--accent-strong);
  text-decoration: underline;
  text-underline-offset: 2px;
}

a:hover {
  color: #b8cfff;
}

.help-text {
  margin: 0.5rem 0 0;
  padding-left: 1.8rem;
  color: var(--text-muted);
  font-size: 0.875rem;
}

.error-text {
  margin: 0.5rem 0 0;
  padding-left: 1.8rem;
  color: var(--danger);
  font-size: 0.875rem;
  font-weight: 500;
}

.submit-btn {
  display: inline-block;
  width: 100%;
  padding: 0.75rem 1rem;
  font: inherit;
  font-weight: 600;
  color: var(--accent-contrast);
  background: var(--accent);
  border: 1px solid var(--accent);
  border-radius: var(--radius);
  cursor: pointer;
  transition:
    background-color 120ms ease,
    transform 80ms ease;
}

.submit-btn:hover {
  background: var(--accent-strong);
  border-color: var(--accent-strong);
}

.submit-btn:active {
  transform: translateY(1px);
}

.status {
  margin: 0.9rem 0 0;
  min-height: 1.25rem;
  font-size: 0.9rem;
  color: #9be7b1;
}

/* Focus indicators — visible on all interactive elements */
:where(input, button, a):focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
  border-radius: 4px;
}

.submit-btn:focus-visible {
  outline-offset: 3px;
}

/* Forced colors / Windows high-contrast */
@media (forced-colors: active) {
  .card,
  .form-field {
    border: 1px solid CanvasText;
  }
  .submit-btn {
    background: ButtonFace;
    color: ButtonText;
    border-color: ButtonText;
  }
  .error-text {
    color: LinkText;
  }
  :where(input, button, a):focus-visible {
    outline-color: Highlight;
  }
}

@media (prefers-reduced-motion: reduce) {
  .submit-btn {
    transition: none;
  }
}
